inputs = ['kzcfh', 'bawkb', 'udbja', 'dfby', 'gyfifx']
outputs = ['kzcfh', 'vfcawkvfc', 'dydvfcja', 'dfvfcy', 'gyfifx']

# Focus on the changed pairs
changed_pairs = []
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        changed_pairs.append((i, inp, out))

print("Changed pairs:")
for idx, inp, out in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{out}'")

print("\nAnalyzing transformations:")
for idx, inp, out in changed_pairs:
    print(f"Index {idx}: '{inp}' -> '{out}'")

    # Let's look at the differences character by character
    min_len = min(len(inp), len(out))
    for i in range(min_len):
        if inp[i] != out[i]:
            print(f"  Position {i}: '{inp[i]}' -> '{out[i]}'")

    if len(out) > len(inp):
        print(f"  Length increased by {len(out) - len(inp)} characters")
    elif len(out) < len(inp):
        print(f"  Length decreased by {len(inp) - len(out)} characters")

    print()

